<?php
/**
 * Guest review grid.
 *
 * Reviews are never generated by the widget; it only renders published
 * p10_review records. Imported sample reviews carry a visible "Sample content"
 * badge and are excluded from structured data.
 *
 * @package Perfect10
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}
if ( ! class_exists( '\Elementor\Widget_Base' ) ) {
	return;
}

/**
 * Reviews widget.
 */
class P10_Elementor_Reviews extends P10_Elementor_Widget {

	/**
	 * Name.
	 *
	 * @return string
	 */
	public function get_name() {
		return 'p10-reviews';
	}

	/**
	 * Title.
	 *
	 * @return string
	 */
	public function get_title() {
		return __( 'Perfect 10 · Reviews', 'perfect10' );
	}

	/**
	 * Icon.
	 *
	 * @return string
	 */
	public function get_icon() {
		return 'eicon-testimonial';
	}

	/**
	 * Controls.
	 */
	protected function register_controls() {
		$this->add_heading_controls( 'heading', array(), 'p10_heading', 'reviews' );

		$this->start_controls_section(
			'query',
			array(
				'label' => __( 'Reviews & Layout', 'perfect10' ),
				'tab'   => \Elementor\Controls_Manager::TAB_CONTENT,
			)
		);
		$this->add_control(
			'limit',
			array(
				'label'   => __( 'Number of reviews', 'perfect10' ),
				'type'    => \Elementor\Controls_Manager::NUMBER,
				'min'     => 1,
				'max'     => 12,
				'default' => 3,
			)
		);
		$this->add_control(
			'featured_only',
			array(
				'label'        => __( 'Featured reviews only', 'perfect10' ),
				'type'         => \Elementor\Controls_Manager::SWITCHER,
				'default'      => 'yes',
				'return_value' => 'yes',
			)
		);
		$this->add_control(
			'section_style',
			array(
				'label'   => __( 'Section treatment', 'perfect10' ),
				'type'    => \Elementor\Controls_Manager::SELECT,
				'default' => 'panel-gold',
				'options' => array(
					''           => __( 'Plain', 'perfect10' ),
					'panel'      => __( 'Panel background', 'perfect10' ),
					'gold-line'  => __( 'Gold hairline', 'perfect10' ),
					'panel-gold' => __( 'Panel + gold hairline', 'perfect10' ),
				),
			)
		);
		$this->add_control(
			'anchor_id',
			array(
				'label'   => __( 'Anchor ID', 'perfect10' ),
				'type'    => \Elementor\Controls_Manager::TEXT,
				'default' => 'p10-reviews',
			)
		);
		p10_register_grid_controls( $this, '{{WRAPPER}} .p10-grid--reviews' );
		$this->end_controls_section();

		$this->start_controls_section(
			'p10_notice_section',
			array(
				'label' => __( 'Trust & Safety', 'perfect10' ),
				'tab'   => \Elementor\Controls_Manager::TAB_CONTENT,
			)
		);
		$this->add_control(
			'show_notice',
			array(
				'label'        => __( 'Show verification note', 'perfect10' ),
				'type'         => \Elementor\Controls_Manager::SWITCHER,
				'default'      => 'yes',
				'return_value' => 'yes',
			)
		);
		$this->add_control(
			'notice',
			array(
				'label'       => __( 'Verification note', 'perfect10' ),
				'type'        => \Elementor\Controls_Manager::TEXTAREA,
				'rows'        => 2,
				'default'     => __( 'Reviews are published only after the guest confirms the engagement. Sample/demo reviews are labelled and are not used in structured data.', 'perfect10' ),
				'condition'   => array( 'show_notice' => 'yes' ),
			)
		);
		$this->end_controls_section();

		$this->add_heading_style_controls();
		p10_register_spacing_controls( $this, '{{WRAPPER}} .p10-section' );
	}

	/**
	 * Render.
	 */
	protected function render() {
		$s      = $this->get_settings_for_display();
		$limit  = isset( $s['limit'] ) ? max( 1, min( 12, (int) $s['limit'] ) ) : 3;
		$only   = ! isset( $s['featured_only'] ) || 'yes' === $s['featured_only'];
		$action = p10_utility_url( 'reviews' );

		if ( $only ) {
			$reviews = p10_get_featured_reviews( $limit );
		} else {
			$reviews = get_posts(
				array(
					'post_type'      => 'p10_review',
					'post_status'    => 'publish',
					'posts_per_page' => $limit,
					'orderby'        => 'date',
					'order'          => 'DESC',
					'no_found_rows'  => true,
				)
			);
		}

		$style  = isset( $s['section_style'] ) ? $s['section_style'] : '';
		$anchor = isset( $s['anchor_id'] ) ? sanitize_title( $s['anchor_id'] ) : '';
		$class  = 'p10-section';
		if ( in_array( $style, array( 'panel', 'panel-gold' ), true ) ) {
			$class .= ' p10-section--panel';
		}
		if ( in_array( $style, array( 'gold-line', 'panel-gold' ), true ) ) {
			$class .= ' p10-section--gold-line';
		}
		$heading = $this->get_heading_html( $s, 'heading', 'reviews', $action );
		?>
		<section class="<?php echo esc_attr( $class ); ?>"<?php echo $anchor ? ' id="' . esc_attr( $anchor ) . '"' : ''; ?>>
			<div class="p10-shell">
				<?php echo $heading; // phpcs:ignore WordPress.Security.EscapeOutput ?>
				<?php if ( $reviews ) : ?>
					<div class="p10-grid p10-grid--reviews p10-dynamic-grid">
						<?php foreach ( $reviews as $i => $review ) : ?>
							<?php get_template_part( 'template-parts/review', null, array( 'review' => $review, 'index' => $i + 1 ) ); ?>
						<?php endforeach; ?>
					</div>
				<?php else : ?>
					<?php echo p10_empty_state( __( 'No published guest reviews yet. Publish a review under Perfect 10 → Reviews; the theme never generates testimonials automatically.', 'perfect10' ) ); // phpcs:ignore WordPress.Security.EscapeOutput ?>
				<?php endif; ?>
				<?php if ( ! isset( $s['show_notice'] ) || 'yes' === $s['show_notice'] ) : ?>
					<p class="p10-reviews-note"><?php echo esc_html( isset( $s['notice'] ) ? $s['notice'] : '' ); ?></p>
				<?php endif; ?>
			</div>
		</section>
		<?php
	}
}
